(() => {
      const csvLangs = get(["languages", "language"], "");
      if (csvLangs && typeof csvLangs === "string") {
        try {
          return JSON.parse(csvLangs);
        } catch {
          return csvLangs
            .split(",")
            .map((t) => t.trim())
            .filter(Boolean);
        }
      }
      return Array.isArray(config.languages) ? config.languages : [];
    })

